$q=db()->prepare('SELECT a.*,p.full_name personnel_name,p.personnel_code FROM assets a LEFT JOIN personnel p ON p.id=a.personnel_id WHERE a.asset_no=?');$q->execute([$no]);$a=$q->fetch();if(!$a){http_response_code(404);exit('تجهیز یافت نشد.');}
$q=db()->prepare('SELECT * FROM asset_disks WHERE asset_no=? ORDER BY disk_index');$q->execute([$no]);$disks=$q->fetchAll();$q=db()->prepare('SELECT * FROM asset_ram_slots WHERE asset_no=? ORDER BY slot_no');$q->execute([$no]);$rams=$q->fetchAll();
$usageRow=[];try{$q=db()->prepare('SELECT * FROM usage_stats WHERE asset_no=?');$q->execute([$no]);$usageRow=$q->fetch()?:[];}catch(PDOException $e){if($e->getCode()!=='42S02')throw $e;$usageRow=[];foreach(['boot_count','normal_shutdown_count','unexpected_shutdown_count','user_shutdown_count','last_boot_time','last_shutdown_time','completed_session_count','current_session_hours','current_session_duration','total_usage_hours','total_usage_duration','average_session_hours','average_session_duration','longest_session_hours','longest_session_duration','collected_at'] as $k)$usageRow[$k]=$a[$k]??null;}
