function showv(mixed $v):string{return is_array($v)?implode('، ',array_map('strval',$v)):(string)$v;}function json_cards(mixed $v):string{if(!is_array($v))return ''; $o='';foreach($v as $x){$o.='<div class="data-card"><strong>'.e(is_array($x)?json_encode($x,JSON_UNESCAPED_UNICODE):$x).'</strong></div>';}return $o;}function hv(array $t,string $k):bool{return isset($t[$k])&&((is_array($t[$k])&&$t[$k])||(!is_array($t[$k])&&trim((string)$t[$k])!==''));}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($no)?> | پرونده تجهیز</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">HWiNFO · پایش سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="report.php">گزارش‌ها</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><div class="eyebrow">پرونده تجهیز</div><h1><?=e($no)?></h1><p class="muted"><?=e($types[$a['asset_type']]??$a['asset_type'])?> · <?=e($a['updated_at'])?></p></div><div class="actions"><?php if($a['source_file']):?><a class="btn" href="source_download.php?asset_no=<?=urlencode($no)?>">CSV منبع</a><?php endif;?><?php if(can_manage_asset_type($a['asset_type'],'edit')):?><a class="btn primary" href="asset_edit.php?asset_no=<?=urlencode($no)?>">ویرایش</a><form method="post" action="asset_delete.php" onsubmit="return confirm('این تجهیز و اطلاعات وابسته حذف شود؟');" style="display:inline"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="asset_no" value="<?=e($no)?>"><button class="btn danger" type="submit">حذف تجهیز</button></form><?php endif;?></div></div>
<section class="asset-summary"><div class="asset-title"><span class="asset-icon"><?=e(mb_substr($types[$a['asset_type']]??'ت',0,1))?></span><div><strong><?=e(trim(($a['manufacturer']??'').' '.($a['model']??''))?:'بدون مدل')?></strong><span><?=e($a['hostname']?:'—')?></span></div></div><div class="summary-item"><span>کاربر / مسئول</span><b><?=e($a['personnel_name']?:($t['UserName']??'—'))?></b></div><div class="summary-item"><span>مکان</span><b><?=e($a['location']?:'—')?></b></div><div class="summary-item"><span>وضعیت</span><b class="badge <?=e($a['status'])?>"><?=e($status[$a['status']]??$a['status'])?></b></div></section>
<section class="panel"><h2>مشخصات پایه</h2><div class="info-grid"><div><span>شماره اموال</span><strong><?=e($a['asset_no'])?></strong></div><div><span>نوع</span><strong><?=e($types[$a['asset_type']]??$a['asset_type'])?></strong></div><div><span>نام دستگاه</span><strong><?=e($a['hostname']?:($t['ComputerName']??'—'))?></strong></div><div><span>سریال</span><strong><?=e($a['serial_no']?:($t['SystemSerial']??'—'))?></strong></div><div><span>پرسنل</span><strong><?=e($a['personnel_name']?:'—')?></strong></div><div><span>مکان</span><strong><?=e($a['location']?:'—')?></strong></div></div></section>
<?php foreach(($sections[$a['asset_type']]??[]) as $title=>$keys):$vis=array_filter($keys,fn($k)=>hv($t,$k));if(!$vis)continue;?><section class="panel"><h2><?=e($title)?></h2><div class="technical-grid"><?php foreach($vis as $k):?><div class="technical-item"><span><?=e($labels[$k]??$k)?></span><?php if(is_array($t[$k])):?><div class="data-cards"><?=json_cards($t[$k])?></div><?php else:?><strong><?=e(showv($t[$k]))?></strong><?php endif;?></div><?php endforeach;?></div></section><?php endforeach;?>
<?php if($a['asset_type']==='computer'):?><section class="panel"><h2>دیسک‌های فیزیکی</h2><div class="data-cards"><?php foreach($disks as $d):?><article class="data-card"><b>Disk <?=e($d['disk_index'])?></b><span><?=e($d['model']?:'بدون مدل')?></span><span>ظرفیت: <?=e($d['size_gb']??'—')?> GB</span><span>Serial: <?=e($d['serial_no']??'—')?></span><span>Interface: <?=e($d['interface_name']??'—')?></span><span>Media: <?=e($d['media']??'—')?></span></article><?php endforeach;?></div></section><section class="panel"><h2>ماژول‌های RAM</h2><div class="data-cards"><?php foreach($rams as $r):?><article class="data-card"><b><?=e($r['slot_no'])?></b><span>وضعیت: <?=e($r['state'])?></span><span>ظرفیت: <?=e($r['capacity_gb']??'—')?> GB</span><span>نوع: <?=e($r['ram_type']??'—')?></span><span>سرعت: <?=e($r['speed_mhz']??'—')?> MHz</span><span>سازنده: <?=e($r['manufacturer']??'—')?></span><span>Part: <?=e($r['part_number']??'—')?></span><span>Serial: <?=e($r['serial_no']??'—')?></span></article><?php endforeach;?></div></section><section class="panel"><h2>پایش زمان و میزان استفاده</h2><div class="technical-grid"><?php foreach($usage as $k=>$label):if(!array_key_exists($k,$usageRow)||$usageRow[$k]===null||$usageRow[$k]==='')continue;?><div class="technical-item"><span><?=e($label)?></span><strong><?=e((string)$usageRow[$k])?></strong></div><?php endforeach;?></div></section><?php endif;?></main></body></html>